CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Purchasing_vVendorWithAddresses` AS select `v`.`BusinessEntityID` AS `BusinessEntityID`,`v`.`Name` AS `Name`,`at`.`Name` AS `AddressType`,`a`.`AddressLine1` AS `AddressLine1`,`a`.`AddressLine2` AS `AddressLine2`,`a`.`City` AS `City`,`sp`.`Name` AS `StateProvinceName`,`a`.`PostalCode` AS `PostalCode`,`cr`.`Name` AS `CountryRegionName` from (((((`Purchasing_Vendor` `v` join `Person_BusinessEntityAddress` `bea` on(`bea`.`BusinessEntityID` = `v`.`BusinessEntityID`)) join `Person_Address` `a` on(`a`.`AddressID` = `bea`.`AddressID`)) join `Person_StateProvince` `sp` on(`sp`.`StateProvinceID` = `a`.`StateProvinceID`)) join `Person_CountryRegion` `cr` on(`cr`.`CountryRegionCode` = `sp`.`CountryRegionCode`)) join `Person_AddressType` `at` on(`at`.`AddressTypeID` = `bea`.`AddressTypeID`));
